import{_ as a,o as n,c as i,a5 as e}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"UC — Identify Task Detail","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-task-workflow/3-6-1-identify-task-detail/spec.md","filePath":"feature/content-task-workflow/3-6-1-identify-task-detail/spec.md"}'),h={name:"feature/content-task-workflow/3-6-1-identify-task-detail/spec.md"};function c(o,t,r,l,s,d){return n(),i("div",null,[...t[0]||(t[0]=[e(`<h1 id="uc-—-identify-task-detail" tabindex="-1">UC — Identify Task Detail <a class="header-anchor" href="#uc-—-identify-task-detail" aria-label="Permalink to &quot;UC — Identify Task Detail&quot;">​</a></h1><p>&gt; <strong>Ưu tiên BA mới 2026-10-15:</strong> xem <a href="./../task-five-state-inline-edit/spec.html">Task năm trạng thái + inline autosave</a>. TODO thay BACKLOG/DETAIL_IDENTIFIED/ASSIGNED; giao việc cần mô tả + deadline hợp lệ, không chuyển trạng thái. IN_REVIEW lưu bước QC/Manager/Client riêng, reject về IN_PROGRESS, bước cuối thành công mới FINISHED. Manager khóa sửa/giao lại sau lần bắt đầu đầu tiên. Phần vòng đời/form cũ bên dưới được giữ làm lịch sử, không phải contract mới. Đợt này chỉ code FR 3.6.1/2; Approval và Comments không được coi là đã hoàn thành.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>FR Code</td><td>3.6.1</td></tr><tr><td>Feature</td><td>Identify Task Detail</td></tr><tr><td>Domain</td><td>Content &amp; Workflow (FR 3.6)</td></tr><tr><td>Role</td><td>MANAGER</td></tr><tr><td>Version</td><td>2.0 (V2 — nghiệp vụ mới, 2026-09-14)</td></tr><tr><td>Trạng thái tài liệu</td><td>BA confirmed Q13; đợt 2026-10-15 đã code workflow/API/UI, chờ nghiệm thu Atlas và review tích hợp</td></tr></tbody></table><h2 id="_1-objective" tabindex="-1">1. Objective <a class="header-anchor" href="#_1-objective" aria-label="Permalink to &quot;1. Objective&quot;">​</a></h2><p>Manager bổ sung yêu cầu đầu vào cho Task trước khi Creator bắt đầu. Giao người thực hiện thuộc FR 3.6.2; ngày đăng dự kiến POST tách khỏi hạn hoàn thành công việc.</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>Là một Manager, tôi muốn bổ sung chi tiết cho 1 Task trong backlog, để chuẩn bị giao việc cụ thể cho Creator.</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ul><li>Task ở backlog chỉ có: tên, yêu cầu đầu ra thô, deadline sơ bộ — CHƯA có người làm, CHƯA có yêu cầu chi tiết.</li><li>Phạm vi đợt này: mô tả yêu cầu, hạn hoàn thành và đầu vào/tham khảo cho POST/LIVESTREAM/SURVEY/EVENT_PLAN/PRESS_RECOMMENDATION. Không làm thay editor Post, kịch bản Livestream, form Survey hoặc nội dung chuyên biệt của thành viên khác.</li><li>Mọi Task có hạn hoàn thành (<code>dueDate</code>). POST có thêm thời điểm đăng dự kiến, độc lập với dueDate; lưu giá trị này không tự lập lịch/publish.</li><li>Task gắn Campaign: hạn hoàn thành từ max(ngày hiện tại, ngày bắt đầu Campaign) đến hết ngày kết thúc theo múi giờ Workspace. Ngày đăng dự kiến POST không trước dueDate và cũng nằm trong Campaign. Task thủ công không gắn Campaign: hạn từ ngày hiện tại trở đi (Q10 confirmed).</li><li>Lần xác định chi tiết đầu tiên: <code>BACKLOG → DETAIL_IDENTIFIED</code>, sẵn sàng Assign (FR 3.6.2).</li><li>Manager được sửa chi tiết ở BACKLOG/DETAIL_IDENTIFIED và ASSIGNED trước khi Creator bắt đầu; chỉnh sửa không đưa Task đã giao trở về backlog hoặc xóa người phụ trách.</li><li>Creator phải bấm <strong>Bắt đầu làm</strong> mới chuyển ASSIGNED → IN_PROGRESS và ghi nhận lần bắt đầu đầu tiên. Mở trang/editor không tính bắt đầu (Q8 confirmed 2026-10-14).</li><li>Sau khi Creator bắt đầu hoặc Task đã vào vòng duyệt thì khóa sửa chi tiết trong phạm vi đợt này. Reject về ASSIGNED không xóa dấu mốc bắt đầu và không mở lại quyền sửa yêu cầu của Manager.</li><li>Chỉ Manager thực tế của đúng Workspace được sửa. Giữ ID, liên kết Campaign/Request, số lượng/kế hoạch đã duyệt và audit hủy Task; không mở lại COMPLETED/CANCELLED.</li><li>Q13 confirmed 2026-10-14: Client active được xem và bình luận mọi Task trong đúng Workspace, kể cả Task Manager tạo thủ công và Task cũ; không phân biệt nội bộ/thường, không có field visibility. Quyền này không cho Client sửa brief, giao việc hoặc sửa content/editor. Cờ requiresClientApproval chỉ quyết định có bước Client duyệt kết quả, không quyết định quyền xem/bình luận.</li></ul><h2 id="_4-ui-ux" tabindex="-1">4. UI / UX <a class="header-anchor" href="#_4-ui-ux" aria-label="Permalink to &quot;4. UI / UX&quot;">​</a></h2><ul><li>Xác nhận UI 2026-10-15: mở Task trong bảng chi tiết phía phải của danh sách, không chuyển sang trang mới. Desktop giữ danh sách tương tác được; màn hình nhỏ dùng bảng trượt có nút đóng. URL <code>/workspaces/:id/tasks?task={taskId}</code> hỗ trợ liên kết trực tiếp và Back/Forward; route detail cũ chuyển về URL này.</li><li>Bảng dùng cùng workflow/form/capabilities hiện có: xem, lưu brief, giao việc và bắt đầu làm; không thay đổi BA/quyền hoặc editor chuyên biệt. Lưu thành công cập nhật danh sách mà không mất bộ lọc/chế độ xem/trang.</li><li>Bàn phím mở được Task, đóng bằng nút hoặc Escape và trả focus về điểm mở. vi/en dùng <code>tasks.panel.*</code> song song; giữ semantic light/dark tokens và layout không tràn viewport.</li></ul><h2 id="_5-api-contract-đe-xuat-can-xac-nhan-khi-thiet-ke-ky-thuat" tabindex="-1">5. API Contract (đề xuất, cần xác nhận khi thiết kế kỹ thuật) <a class="header-anchor" href="#_5-api-contract-đe-xuat-can-xac-nhan-khi-thiet-ke-ky-thuat" aria-label="Permalink to &quot;5. API Contract (đề xuất, cần xác nhận khi thiết kế kỹ thuật)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PATCH /api/v1/workspaces/{id}/tasks/{taskId}/detail</span></span>
<span class="line"><span>{ &quot;description&quot;, &quot;dueDate&quot;, &quot;plannedPublishAt&quot;?: &quot;ISO timestamp for POST&quot;, &quot;inputReferences&quot;?: [...], &quot;expectedRevision&quot; }</span></span>
<span class="line"><span>→ 200 { &quot;success&quot;: true, &quot;data&quot;: { ...updated task... } }</span></span></code></pre></div><p>Tên field trên là đề xuất kỹ thuật, chưa final. Lần đầu chuyển DETAIL_IDENTIFIED; sửa trước bắt đầu giữ trạng thái hiện tại. Không nhận blob typeMetadata tùy ý để ghi đè nội dung module khác.</p><h2 id="_6-error-handling" tabindex="-1">6. Error Handling <a class="header-anchor" href="#_6-error-handling" aria-label="Permalink to &quot;6. Error Handling&quot;">​</a></h2><ul><li>Lần xác định đầu tiên không phải BACKLOG hoặc sửa sau khi bắt đầu/terminal → 409 theo lỗi trạng thái được chốt trong plan. Quy tắc cũ “mọi sửa chỉ BACKLOG” được thay thế bởi xác nhận 2026-10-14.</li><li>Không phải Manager của Workspace này → 403 <code>FORBIDDEN</code>.</li></ul><h2 id="_7-edge-cases" tabindex="-1">7. Edge Cases <a class="header-anchor" href="#_7-edge-cases" aria-label="Permalink to &quot;7. Edge Cases&quot;">​</a></h2><ul><li>Task sinh từ Content Request đã có <code>description</code> gốc từ Client → Manager có thể giữ nguyên hoặc bổ sung thêm, không bắt buộc viết lại từ đầu.</li><li>Campaign đã hết ngày hợp lệ → không có hạn mới hợp lệ để lưu; hiển thị lỗi thay vì tự kéo dài timeline. API vẫn kiểm tra khi vượt UI hoặc dữ liệu thay đổi đồng thời.</li></ul><h2 id="_8-definition-of-done" tabindex="-1">8. Definition of Done <a class="header-anchor" href="#_8-definition-of-done" aria-label="Permalink to &quot;8. Definition of Done&quot;">​</a></h2><ul><li>Điền chi tiết thành công, Task chuyển đúng trạng thái tiếp theo.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>Không sửa editor/Approval, không tự schedule/publish, không làm module chuyên biệt hoặc views E51-05.</li></ul><h2 id="i18n-va-theme" tabindex="-1">i18n và theme <a class="header-anchor" href="#i18n-va-theme" aria-label="Permalink to &quot;i18n và theme&quot;">​</a></h2><p>Nhãn/form/errors dùng namespace <code>tasks</code>: <code>detail.*</code>, <code>fields.*</code>, <code>status.*</code>, <code>actions.*</code>, <code>errors.*</code>, <code>common.*</code> (vi/en song song). Semantic light/dark tokens; loading/empty/forbidden/error/success/conflict rõ ràng, lỗi cạnh field, không mất input khi conflict. Date picker giới hạn ngay khi chọn theo Q10; backend vẫn xác minh. Không có bộ chọn nội bộ/thường. Xem <a href="./plan.html">plan</a>, <a href="./task.html">task</a>, <a href="./test.html">test</a>.</p><h2 id="tham-chieu-ba" tabindex="-1">Tham chiếu BA <a class="header-anchor" href="#tham-chieu-ba" aria-label="Permalink to &quot;Tham chiếu BA&quot;">​</a></h2><p><a href="./../../../ba/05-content-task-workflow.html">05-content-task-workflow.md</a>, <a href="./../task-detail-assignment-comments-roadmap.html">roadmap và quyết định BA</a>.</p><h2 id="đot-tiep-tuc-2026-10-15" tabindex="-1">Đợt tiếp tục 2026-10-15 <a class="header-anchor" href="#đot-tiep-tuc-2026-10-15" aria-label="Permalink to &quot;Đợt tiếp tục 2026-10-15&quot;">​</a></h2><p>Dùng danh sách Task thật vừa tích hợp làm điểm vào; mở bảng chi tiết bên phải bằng ID Task, không tạo list/backlog thứ hai. Đọc workflow riêng cho mọi thành viên active; form chỉ xuất hiện theo capabilities backend. Hiển thị lý do khóa khi thiếu foundation, legacy thiếu bằng chứng bắt đầu, Task đã bắt đầu/terminal hoặc Campaign hoàn thành. Không tự backfill để mở khóa Task cũ. Giữ contract editor/Approval; comments thuộc đợt sau.</p>`,28)])])}const k=a(h,[["render",c]]);export{g as __pageData,k as default};
